-- ============================================
-- LUMA — Thème 4 : LONG 3/3 x4 — Aider un autre passager en difficulté
-- ============================================


update scenarios set content = '{"characters": {"elderly_man": "le passager âgé", "staff": "le personnel", "gate_agent": "l''agent de porte"}, "start_node": "n1", "nodes": {"n1": {"speaker": "you_thought", "text": "(You notice an elderly man near your gate, looking at his phone anxiously, muttering to himself.)", "text_fr": "(Vous remarquez un homme âgé près de votre porte, regardant anxieusement son téléphone, marmonnant.)", "choices": [{"text": "(Approach and ask if he needs help.)", "text_fr": "(Approche et demande s''il a besoin d''aide.)", "next": "n2"}, {"text": "(Observe a bit longer before deciding whether to intervene.)", "text_fr": "(Observe encore un peu avant de décider d''intervenir.)", "next": "n2b"}]}, "n2": {"speaker": "elderly_man", "text": "Oh — sorry, do you speak English? I''m quite lost, my flight seems to have left without me.", "text_fr": "Oh — désolé, vous parlez anglais ? Je suis assez perdu, mon vol semble être parti sans moi.", "choices": [{"text": "Yes, I speak English. Let''s figure this out together.", "text_fr": "Oui, je parle anglais. Trouvons une solution ensemble.", "next": "n3"}, {"text": "I do — can I see your ticket to understand what happened?", "text_fr": "Oui — je peux voir votre billet pour comprendre ce qui s''est passé ?", "next": "n3"}]}, "n2b": {"speaker": "elderly_man", "text": "(He looks more distressed, checking his watch repeatedly.)", "text_fr": "(Il semble plus en détresse, vérifiant sa montre de façon répétée.)", "choices": [{"text": "(Decide to step in and offer help.)", "text_fr": "(Décide d''intervenir et d''offrir de l''aide.)", "next": "n2"}]}, "n3": {"speaker": "elderly_man", "text": "Here''s my ticket — I think I was at the wrong gate the whole time.", "text_fr": "Voici mon billet — je pense que j''étais à la mauvaise porte depuis le début.", "choices": [{"text": "(Check the ticket) Ah, your gate is actually B15, not B5 — an easy mix-up.", "text_fr": "(Vérifie le billet) Ah, votre porte est en fait B15, pas B5 — une confusion facile.", "next": "n4"}]}, "n4": {"speaker": "elderly_man", "text": "Oh no, is there still time? I don''t want to miss this flight, my daughter is waiting for me.", "text_fr": "Oh non, il reste encore du temps ? Je veux pas rater ce vol, ma fille m''attend.", "choices": [{"text": "Let''s check the boarding time and hurry there together.", "text_fr": "Vérifions l''heure d''embarquement et dépêchons-nous ensemble.", "next": "n5"}, {"text": "Let me ask a staff member if the gate is still boarding.", "text_fr": "Laissez-moi demander à un membre du personnel si la porte embarque encore.", "next": "n5b"}]}, "n5": {"speaker": "you_thought", "text": "(You check the departure board — boarding closes in 12 minutes.)", "text_fr": "(Vous vérifiez le tableau des départs — l''embarquement ferme dans 12 minutes.)", "choices": [{"text": "We can make it if we go now — let''s walk quickly together.", "text_fr": "On peut y arriver si on y va maintenant — marchons vite ensemble.", "next": "n6"}]}, "n5b": {"speaker": "staff", "text": "Gate B15 is still boarding, but it closes soon!", "text_fr": "La porte B15 embarque encore, mais ça ferme bientôt !", "choices": [{"text": "Thank you! Let''s hurry, sir, we don''t have much time.", "text_fr": "Merci ! Dépêchons-nous, monsieur, on n''a pas beaucoup de temps.", "next": "n6"}]}, "n6": {"speaker": "elderly_man", "text": "(Struggling to walk quickly with his cane and heavy bag.)", "text_fr": "(Ayant du mal à marcher vite avec sa canne et son sac lourd.)", "choices": [{"text": "Here, let me carry your bag so you can move faster.", "text_fr": "Tenez, laissez-moi porter votre sac pour que vous puissiez avancer plus vite.", "next": "n7"}, {"text": "Let''s take it steady, I''ll stay right by your side.", "text_fr": "Allons-y tranquillement, je reste juste à côté de vous.", "next": "n7b"}]}, "n7": {"speaker": "elderly_man", "text": "Oh, thank you, that''s very kind of you, young one.", "text_fr": "Oh, merci, c''est très gentil de votre part, jeune homme/dame.", "choices": [{"text": "Of course, we''re almost there, just a bit further.", "text_fr": "Bien sûr, on y est presque, juste un peu plus loin.", "next": "n8"}]}, "n7b": {"speaker": "elderly_man", "text": "I appreciate you not rushing me, I get a bit anxious when hurried.", "text_fr": "J''apprécie que vous ne me pressiez pas, je deviens un peu anxieux quand on me presse.", "choices": [{"text": "Take your time, we''ll make it together.", "text_fr": "Prenez votre temps, on va y arriver ensemble.", "next": "n8"}]}, "n8": {"speaker": "you_thought", "text": "(You both arrive at gate B15, slightly out of breath, just as final boarding is announced.)", "text_fr": "(Vous arrivez tous les deux à la porte B15, un peu essoufflés, juste au moment où l''embarquement final est annoncé.)", "choices": [{"text": "(Help him show his boarding pass to the gate agent.)", "text_fr": "(Aide-le à montrer sa carte d''embarquement à l''agent de porte.)", "next": "n9"}]}, "n9": {"speaker": "gate_agent", "text": "Just in time, sir! Please head down the jet bridge now.", "text_fr": "Juste à temps, monsieur ! Dirigez-vous vers la passerelle maintenant.", "choices": [{"text": "(Turn to the elderly man) You made it! Safe travels to your daughter.", "text_fr": "(Te tournes vers l''homme âgé) Vous avez réussi ! Bon voyage jusqu''à votre fille.", "next": "n10"}]}, "n10": {"speaker": "elderly_man", "text": "Thank you so much, truly. I don''t know what I would have done without your help.", "text_fr": "Merci beaucoup, vraiment. Je sais pas ce que j''aurais fait sans votre aide.", "choices": [{"text": "I''m just glad I could help — have a wonderful trip.", "text_fr": "Je suis juste content d''avoir pu aider — bon voyage.", "next": "end_grateful"}, {"text": "It was truly my pleasure. Give your daughter a big hug for me!", "text_fr": "Ce fut un vrai plaisir. Faites un gros câlin à votre fille de ma part !", "next": "end_grateful"}]}, "end_grateful": {"speaker": "elderly_man", "text": "(Smiling warmly) I will. Bless you, young one. Safe travels to you too.", "text_fr": "(Sourit chaleureusement) Je le ferai. Que Dieu vous bénisse, jeune ami. Bon voyage à vous aussi.", "end": true, "ending_label": "Un acte de gentillesse qui a fait la différence 🙏✈️"}}}'::jsonb, is_playable = true
where title = 'Aider un autre passager en difficulté'
  and theme_id = (select id from scenario_themes where position = 4 and language_id = (select id from languages where code = 'en'));
